import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyCuDan = () => {
    // 1. STATE QUẢN LÝ DỮ LIỆU (Sẵn sàng để thay bằng dữ liệu từ Backend)
    const [selectedRoom, setSelectedRoom] = useState(null);
    const [info, setInfo] = useState(null);
    const [loading, setLoading] = useState(false);

    // 2. TẠO DANH SÁCH PHÒNG (Dữ liệu tĩnh này có thể giữ lại hoặc lấy từ API sau này)
    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // 3. EFFECT LẮNG NGHE THAY ĐỔI (Đầu chờ kết nối API)
    useEffect(() => {
        if (!selectedRoom) return;

        // Hàm này sau này chỉ cần thay nội dung bên trong bằng lệnh Axios/Fetch
        const fetchResidentData = async () => {
            setLoading(true);
            try {
                // GIẢ LẬP: Sau này thay đoạn này bằng: const res = await axios.get(`/api/room/${selectedRoom}`)
                setTimeout(() => {
                    const mockDataFromBackend = {
                        "101": { name: "Nguyễn Văn Vinh", gender: "Nam", phone: "0905 123 456", members: 3, parking: "Khu A - 01" },
                        "102": { name: "Lê Thị Hoa", gender: "Nữ", phone: "0912 999 888", members: 2, parking: "Khu B - 05" },
                    };

                    setInfo(mockDataFromBackend[selectedRoom] || {
                        name: "Chưa có dữ liệu",
                        gender: "---",
                        phone: "---",
                        members: 0,
                        parking: "---"
                    });
                    setLoading(false);
                }, 400); // Tạo độ trễ nhẹ để trải nghiệm giống thật
            } catch (error) {
                console.error("Backend Error:", error);
                setLoading(false);
            }
        };

        fetchResidentData();
    }, [selectedRoom]);

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)'
        }} className="glass-card">

            <div style={{ padding: '20px', color: '#fff' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)', fontWeight: '700' }}>
                    ADMIN: QUẢN LÝ CƯ DÂN
                </h2>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '25px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG (Sẵn sàng để map từ danh sách Backend) */}
                <div className="custom-scrollbar" style={{ 
                    width: '210px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', alignContent: 'flex-start', overflowY: 'auto',
                    padding: '12px', backgroundColor: 'rgba(0,0,0,0.3)',
                    borderRadius: '20px', border: '1px solid rgba(255,255,255,0.1)'
                }}>
                    {allRooms.map(room => (
                        <div 
                            key={room} 
                            onClick={() => setSelectedRoom(room)}
                            style={{ 
                                background: selectedRoom === room ? '#8b5e5e' : 'rgba(255,255,255,0.85)', 
                                color: selectedRoom === room ? 'white' : '#333',
                                padding: '8px 0', borderRadius: '8px', textAlign: 'center', 
                                fontSize: '11px', fontWeight: 'bold', cursor: 'pointer', transition: '0.2s'
                            }}
                        >
                            {room}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: HIỂN THỊ CHI TIẾT (Kiến trúc dữ liệu động) */}
                <div style={{ 
                    flex: 1, backgroundColor: '#ffffff', borderRadius: '30px', 
                    padding: '40px', display: 'flex', flexDirection: 'column',
                    color: '#000', boxShadow: '0 10px 30px rgba(0,0,0,0.2)', position: 'relative'
                }}>
                    {loading ? (
                        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '20px', color: '#8b5e5e' }}>
                            Đang tải thông tin phòng {selectedRoom}...
                        </div>
                    ) : selectedRoom && info ? (
                        <div style={{ animation: 'fadeIn 0.4s ease-out' }}>
                            <div style={{ marginBottom: '35px' }}>
                                <h1 style={{ fontSize: '65px', margin: 0, color: '#222', fontWeight: '800' }}>
                                    PHÒNG {selectedRoom}
                                </h1>
                                <div style={{ width: '100px', height: '5px', background: '#8b5e5e' }}></div>
                            </div>

                            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
                                <InfoBlock label="Tên chủ hộ" value={info.name} bold />
                                <InfoBlock label="Giới tính" value={info.gender} />
                                <InfoBlock label="Số điện thoại" value={info.phone} color="#007bff" />
                                <InfoBlock label="Thành viên" value={`${info.members} người`} />
                                <InfoBlock label="Bãi đỗ xe" value={info.parking} />
                            </div>
                        </div>
                    ) : (
                        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', color: '#aaa', fontSize: '20px', fontStyle: 'italic' }}>
                            Vui lòng chọn số phòng để xem dữ liệu cư dân...
                        </div>
                    )}
                </div>
            </div>
            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.2); border-radius: 10px; }
                @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
            `}</style>
        </div>
    );
};

// Component con tối ưu để tái sử dụng
const InfoBlock = ({ label, value, bold, color }) => (
    <div style={{ display: 'flex', borderBottom: '1px solid #f0f0f0', paddingBottom: '15px', alignItems: 'center' }}>
        <span style={{ width: '220px', fontSize: '18px', color: '#777' }}>{label}</span>
        <span style={{ fontSize: '22px', fontWeight: bold ? '700' : '500', color: color || '#333' }}>
            {value}
        </span>
    </div>
);

export default QuanLyCuDan;
